cases=[]
def add(cid,title,papers,prompts,routes,constraints,boundaries,failures,relation=None,split='navigation_challenge'):
 us=[u for u in U if u['paperId'] in papers]
 case=dict(id=cid,title=title,split=split,scientificGoldLabel=False,questionPrompts=prompts,entryRoutes=routes,requiredWitnessPaperIds=papers,definingConstraints=constraints,boundaryPrompts=boundaries,failureConditions=failures,witnesses=[dict(unitId=u['id'],paperId=u['paperId'],lens=u['lens'],text=u['text'],nodeIds=u['evidence']['sourceNodeIds'],evidenceIds=u['evidence']['anchors'],sourceSha256=u['evidence']['sourceSha256']) for u in us])
 if relation:
  r=R[relation];case['reviewWitness']={k:r[k] for k in ['taskId','contextRevision','receiptPath','receiptSha256','status','promotionWithheld','relationCategory','direction','exactAssertion','evidenceIds','readerNote']}
 cases.append(case)
